import json,collections
meds={}
for l in open('Medication.ndjson'):
    m=json.loads(l)
    for i in m.get('identifier',[]):
        if i['system'].endswith('medication-name'): meds[m['id']]=i['value']
mrs=[json.loads(l) for l in open('MedicationRequest.ndjson')]
def name(m):
    ref=m.get('medicationReference',{}).get('reference','').split('/')[-1]
    if ref in meds: return meds[ref]
    cc=m.get('medicationCodeableConcept')
    if cc: return cc['coding'][0].get('code') or cc['coding'][0].get('display')
    return 'Medication/'+ref
fut=[m for m in mrs if m.get('dispenseRequest',{}).get('validityPeriod',{}).get('end','')>'2026-09-24']
print(len(fut))
c=collections.Counter(name(m) for m in fut)
for k,v in c.most_common(): print(v,k)
print()
for m in fut[:5]: print(json.dumps(m,indent=1))
EOF

