    if o.get('effectiveDateTime','')>='2024':
        bylab[o['subject']['reference'].split('/')[-1]].append(o)
conds=collections.defaultdict(list)
for l in open('Condition.ndjson'):
    c=json.loads(l)
    conds[c['subject']['reference'].split('/')[-1]].append(c)

os.makedirs('doss',exist_ok=True)
for pid in alive:
    p=P[pid]
    L=[]
    L.append(f"PATIENT {pid} born {p['birthDate']} {p['gender']}")
    L.append("--- ECGs ---")
    for e in sorted(ecg[pid],key=lambda x:x['time']): L.append(f"  {e['ecg']} {e['time']}")
    L.append("--- synthetic med orders ---")
    for m in sorted(synmr[pid],key=lambda m:m['authoredOn']):
        ref=m.get('medicationReference',{}).get('reference','').split('/')[-1]
        vp=m.get('dispenseRequest',{}).get('validityPeriod',{})
        di=m.get('dosageInstruction',[{}])[0]
        L.append(f"  {m['id']} {m['authoredOn'][:16]} {meds.get(ref)} {di.get('text')} {di.get('timing',{}).get('code',{}).get('coding',[{}])[0].get('code')} valid {vp.get('start','')[:10]}..{vp.get('end','')[:10]} status={m['status']} enc={m.get('encounter',{}).get('reference','').split('/')[-1]}")
    L.append("--- conditions (AF/flutter/bleed/stroke etc) ---")
    for c in conds[pid]:
        cd=c['code']['coding'][0]
        L.append(f"  {c['id']} {cd['code']} {cd.get('display')}")
    L.append("--- labs INR/K/Mg since 2024 ---")
    for o in sorted(bylab[pid],key=lambda o:o['effectiveDateTime']):
        cd=o['code']['coding'][0]
        v=o.get('valueQuantity',{}) or {}
        L.append(f"  {o['id']} {o['effectiveDateTime'][:16]} {cd.get('display')} {v.get('value')} {v.get('unit')} {o.get('valueString','')}")
    L.append("--- notes ---")
    for d in sorted(bysubj[pid],key=lambda d:d['date']):
        role=[e['valueCode'] for e in d.get('extension',[]) if e['url'].endswith('author-role')]
        L.append(f"### {d['id']} {d['date']} type={d['type']['coding'][0]['display']} author={d.get('author',[{}])[0].get('display')} role={role} enc={d.get('context',{}).get('encounter',[{}])[0].get('reference','').split('/')[-1]}")
        L.append(base64.b64decode(d['content'][0]['attachment']['data']).decode())
    open(f'doss/{pid}.txt','w').write('\n'.join(L))
print('done')
import subprocess
print(subprocess.run(['du','-sh','doss'],capture_output=True,text=True).stdout)
