import json,numpy as np,ecg3,collections
need=json.load(open('need_ecg.json'))
byp=collections.defaultdict(list)
for e in need: byp[e['patient']].append(e)
rows=[]
res={}
for pid,es in byp.items():
    es.sort(key=lambda x:x['time'])
    for k,e in enumerate(es):
        o=ecg3.analyze(e['ecg'])
        M=o['_M'];a=o['_a'];fs=o['_fs'];qon=o['_qon'];qoff=o['_qoff']
        amp={}
        for i,l in enumerate(ecg3.LEADS):
            seg=M[i,qon:qoff]
            amp[l]=float(seg.max()+seg.min())
        axB=float(np.degrees(np.arctan2(amp['aVF'],amp['I'])))
        p=o['p'] or {}
        res[e['ecg']]={k2:v for k2,v in o.items() if not k2.startswith('_')}
        res[e['ecg']]['axisB']=axB
        res[e['ecg']]['is_last']= (k==len(es)-1)
        res[e['ecg']]['patient']=pid
        res[e['ecg']]['time']=e['time']
        rows.append([pid[:8],'LAST' if k==len(es)-1 else 'prev',e['time'][:10],e['ecg'],round(o['rate']),round(o['rr_cv'],2),round(o['rmssd']),
                     round(o['qrs_ms']),round(o['qt']),round(o['qtc']),round(p.get('pr',-1)),round(1000*p.get('prom',0)),round(p.get('cc') or -1,2),
                     round(o['axis']),round(axB),o['pace']['n'],round(o['pace']['max'],2)])
json.dump(res,open('ecgfinal.json','w'),default=float)
print('\t'.join(['pat','w','date','ecg','rate','rrcv','rmssd','qrs','qt','qtc','PR','Pprom','Pcc','axA','axB','pcN','pcMx']))
for r in sorted(rows): print('\t'.join(str(x) for x in r))
EOF

